import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult
from azure.core.credentials import AzureKeyCredential

def extract_invoice_data(invoice_file_path: str) -> dict:
    """
    Extracts vendor, date, total, and line-item fields from an invoice using Azure Document Intelligence.

    Args:
        invoice_file_path: The path to the invoice file (e.g., PDF, JPG, PNG).

    Returns:
        A dictionary containing the extracted invoice data.
    """
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError(
            "Please set the AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and "
            "AZURE_DOCUMENT_INTELLIGENCE_KEY environment variables."
        )

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    with open(invoice_file_path, "rb") as f:
        invoice_document = f.read()

    # The prebuilt-invoice model extracts invoice-specific fields
    poller = document_intelligence_client.begin_analyze_document(
        "prebuilt-invoice", invoice_document, content_type="application/octet-stream"
    )
    result: AnalyzeResult = poller.result()

    extracted_data = {
        "vendor": None,
        "date": None,
        "total": None,
        "line_items": [],
    }

    if result.documents:
        # Assuming the first document is the relevant invoice
        invoice = result.documents[0]

        if invoice.fields:
            if "VendorName" in invoice.fields and invoice.fields["VendorName"].value:
                extracted_data["vendor"] = invoice.fields["VendorName"].value
            if "InvoiceDate" in invoice.fields and invoice.fields["InvoiceDate"].value:
                extracted_data["date"] = invoice.fields["InvoiceDate"].value.isoformat()
            if "InvoiceTotal" in invoice.fields and invoice.fields["InvoiceTotal"].value:
                # Value may be CurrencyValue which has amount and currencyCode
                total_field = invoice.fields["InvoiceTotal"].value
                if hasattr(total_field, 'amount'):
                    extracted_data["total"] = f"{total_field.amount} {total_field.currency_symbol or ''}".strip()
                else:
                    extracted_data["total"] = str(total_field)


            if "Items" in invoice.fields and invoice.fields["Items"].value:
                for item_field in invoice.fields["Items"].value:
                    item_data = {}
                    if item_field.value and isinstance(item_field.value, dict):
                        # Each item_field.value is a dict of sub-fields for the line item
                        item_fields = item_field.value
                        if "Description" in item_fields and item_fields["Description"].value:
                            item_data["description"] = item_fields["Description"].value
                        if "Quantity" in item_fields and item_fields["Quantity"].value:
                            item_data["quantity"] = item_fields["Quantity"].value
                        if "UnitPrice" in item_fields and item_fields["UnitPrice"].value:
                            item_data["unit_price"] = item_fields["UnitPrice"].value
                        if "Amount" in item_fields and item_fields["Amount"].value:
                            item_data["amount"] = item_fields["Amount"].value
                    extracted_data["line_items"].append(item_data)

    return extracted_data
